import functools

def memoize(fn):
    cache = {}
    @functools.wraps(fn)
    def wrap(*args, **kwargs):
        if args not in cache:
            cache[args] = fn(*args, **kwargs)
        return cache[args]
    wrap.cache = cache
    return wrap

