class IntervalSet:
    """Set of integers stored as half-open [start, end) intervals."""

    def __init__(self):
        self._iv = []

    def add(self, start, end):
        self._iv.append((start, end))
        self._iv.sort()
        merged = []
        for s, e in self._iv:
            if merged and s < merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], e))
            else:
                merged.append((s, e))
        self._iv = merged

    def remove(self, start, end):
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                out.append((s, e))
            else:
                if s < start:
                    out.append((s, start))
                if e > end:
                    out.append((end, e))
        self._iv = out

    def contains(self, x):
        return any(s <= x < e for s, e in self._iv)

    def covered(self, a, b):
        return sum(max(0, min(e, b) - max(s, a)) for s, e in self._iv)

    def gaps(self, a, b):
        return []

    def total(self):
        return sum(e - s for s, e in self._iv)

    def intervals(self):
        return list(self._iv)

