class InsufficientFunds(Exception):
    pass


class Wallet:
    def __init__(self, balance):
        self.balance = balance

    def charge(self, cents):
        if cents > self.balance:
            raise InsufficientFunds(cents)
        self.balance -= cents

    def refund(self, cents):
        self.balance += cents

