def leaves(d, prefix=""):
    """Flatten a nested dict to {'a.b': value}; lists and scalars are leaves."""
    out = {}
    for k, v in d.items():
        path = prefix + k
        if isinstance(v, dict):
            out.update(leaves(v, path + "."))
        else:
            out[path] = v
    return out


def set_path(d, path, value):
    parts = path.split(".")
    for p in parts[:-1]:
        d = d.setdefault(p, {})
    d[parts[-1]] = value

