def group_anagrams(words):
    groups, used = [], set()
    for i, w in enumerate(words):
        if i in used:
            continue
        g = [w]
        for j in range(i + 1, len(words)):
            if j not in used and sorted(words[j].lower()) == sorted(w.lower()):
                g.append(words[j]); used.add(j)
        groups.append(g)
    return groups

